package steps

import (
	"bytes"
	"fmt"
	"os/exec"
	"strings"
)

//truebdd:concept when "operation"
func concept40523ceb26a25e37e78222ac562623f48c38b52711218d94fe5cadea337eebba(state *State, args []string) error {
	if len(args) != 3 {
		return fmt.Errorf("when operation: expected 3 captures (exact, operation, number), got %d", len(args))
	}
	exact, operation, number := args[0], args[1], args[2]

	// The Calculator CLI document declares both commands as
	// "go run ./services/calc <command> ... from the host root"; the suite's
	// tests run in tests/calc, so the host root is two levels up.
	const hostRoot = "../.."

	var command string
	switch operation {
	case "halves":
		command = "halve"
	case "doubles":
		command = "double"
	default:
		return fmt.Errorf("when operation: the step names operation %q, which is neither halves nor doubles", operation)
	}

	cmdArgs := []string{"run", "./services/calc", command}
	if exact != "" {
		if command != "halve" {
			return fmt.Errorf("when operation: the Calculator CLI declares --exact only for halve, not for %s", command)
		}
		cmdArgs = append(cmdArgs, "--exact")
	}
	cmdArgs = append(cmdArgs, number)

	cmd := exec.Command("go", cmdArgs...)
	cmd.Dir = hostRoot
	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	if err := cmd.Run(); err != nil {
		return fmt.Errorf("when operation: go %s: %w: %s", strings.Join(cmdArgs, " "), err, strings.TrimSpace(stderr.String()))
	}

	state.Output = strings.TrimRight(stdout.String(), "\r\n")
	return nil
}

package steps

import (
	"fmt"
	"regexp"
)

//truebdd:concept then "output"
func concept95123e5878d35715c67b1f901cd0d6e1fcafc896021616abdece460efff6ed7e(state *State, args []string) error {
	if len(args) != 2 {
		return fmt.Errorf("then output: expected 2 captures (comparison, pattern), got %d", len(args))
	}
	comparison, pattern := args[0], args[1]

	// The when "operation" step keeps the command's stdout in state.Output with
	// its trailing newline already stripped; this step only observes it.
	output := state.Output

	expression, err := regexp.Compile(pattern)
	if err != nil {
		return fmt.Errorf("then output: the step's pattern %q is not a valid regular expression: %w", pattern, err)
	}
	matched := expression.MatchString(output)

	switch comparison {
	case "matches":
		if !matched {
			return fmt.Errorf("then output: the calculator's output %q does not match %q", output, pattern)
		}
	case "does not match":
		if matched {
			return fmt.Errorf("then output: the calculator's output %q matches %q, but the step requires no match", output, pattern)
		}
	default:
		return fmt.Errorf("then output: the step says %q, which is neither matches nor does not match", comparison)
	}
	return nil
}

package steps

func Register(suite Registrar) {

	suite.Step("^the Owner (?:(exactly) )?(halves|doubles) (-?\\d+)$", concept40523ceb26a25e37e78222ac562623f48c38b52711218d94fe5cadea337eebba)

	suite.Step("^the calculator's output (matches|does not match) (.+)$", concept95123e5878d35715c67b1f901cd0d6e1fcafc896021616abdece460efff6ed7e)
}
